	["<Assistant_Title1>Favor of the War Bishop</>\n<Assistant_Title2>Achievement Category: </>Growth - Sealed Artifact\n<Assistant_Title2>Unlock Condition: </>Obtain 1 Extraordinary material with the <战争主教> trait"] = "<Assistant_Title1> Favor do Bispo de Guerra </> \n <Assistant_Title2> Categoria de conquista: </> Crescimento - Artefato Selado\n <Assistant_Title2> Condição de desbloqueio: </> Obtenha 1 material extraordinário com a característica <War Bishop>",
	["<Assistant_Title1>Gift of the Fighter</>\n<Assistant_Title2>Achievement Category: </>Cultivation-Sealed Artifact\n<Assistant_Title2>Unlock Condition: </>Obtain 1 Beyonder material with the <格斗家> affix"] = "<Assistant_Title1> Presente do Lutador </> \n <Assistant_Title2> Categoria de conquista: </> Artefato selado por cultivo\n <Assistant_Title2> Condição de desbloqueio: </> Obtenha 1 Beyonder material com o afixo <Fighter>",
	["<Assistant_Title1>Gift of the Guardian</>\n<Assistant_Title2>Achievement Category: </>Cultivation-Sealed Artifact\n<Assistant_Title2>Unlock Condition: </>Obtain 1 Beyonder material with the <守护者> affix"] = "<Assistant_Title1> Presente do Guardião </> \n <Assistant_Title2> Categoria de conquista: </> Artefato selado por cultivo\n <Assistant_Title2> Condição de desbloqueio: </> Obtenha 1 Beyonder material com o afixo <Guardian>",
	["<Assistant_Title1>Gift of the Hypnotist</>\n<Assistant_Title2>Achievement Category: </>Growth - Sealed Artifact\n<Assistant_Title2>Unlock Condition: </>Obtain 1 Extraordinary material with the <催眠师> trait"] = "<Assistant_Title1> Presente do Hipnotizador </> \n <Assistant_Title2> Categoria de conquista: </> Crescimento - Artefato Selado\n <Assistant_Title2> Condição de desbloqueio: </> Obtenha 1 material extraordinário com a característica <Hypnotist>",
