	["{\n\"不指定\":\"\",\n\"全体敌方玩家\": \"Enemy(Player)\",\n\"全体敌方玩家（包含尸体）\": \"Enemy(Player)(IncludeDead)\"\n}"] = "{\n \"Não especificado\": \"\", \n \"Todos os jogadores inimigos\": \"Enemy(Player)\", \n \"Todos os jogadores inimigos (incluindo cadáveres)\": \"Enemy(Player)(IncludeDead)\" \n}",
