	["{\n\"全体玩家\": \"0\",\n\"技能/buff持有者\": \"1\",\n\"锁定目标\": \"2\"\n}"] = "{\n \"Todos os jogadores\": \"0\", \n \"Titular de habilidade/buff\": \"1\", \n \"Alvo bloqueado\": \"2\" \n}",
