	["历史"] = "História",
	["历史之回响"] = "Eco da História",
	["历史之涌"] = "Surto da História",
	["历史会指引你。"] = "A história irá guiá-lo.",
	["历史余烬"] = "Brasa Histórica",
	["历史信息"] = "Informações Históricas",
	["历史冲击"] = "Choque Histórico",
	["历史动态"] = "Atualizações históricas",
	["历史哲人"] = "Filósofo Histórico",
	["历史喊话"] = "Gritar História",
	["历史回响"] = "Eco Histórico",
	["历史因为人们的视角不同，呈现出不一样的真相。我可以先跟你讲讲鲁恩的地理和气候。"] = "A história apresenta verdades diferentes devido às diferentes perspectivas das pessoas. Posso falar primeiro sobre a geografia e o clima de Loen.",
	["历史孔隙"] = "Vazio histórico",
	["历史学似乎也变得火热了起来……"] = "A história parece ter se tornado popular também...",
	["历史学家"] = "Historiador",
	["历史学者·一"] = "Historiador I",
	["历史学者·二"] = "Historiador II",
	["历史就会在此刻改变！因蒂斯将统一北大陆！"] = "A história vai mudar neste momento! Intis unificará o Continente Norte!",
	["历史悠久的日记"] = "Diário Histórico",
	["历史战绩"] = "Histórico de partidas",
	["历史投影"] = "Projeção Histórica",
	["历史投影的微弱回响，记录着封印物曾经的力量碎片。用它唤醒沉睡的投影，让危险逐渐显露真容。"] = "Um leve eco de uma projeção histórica, registrando fragmentos do antigo poder do Artefato Selado. Use-o para despertar a projeção adormecida e deixar o perigo revelar gradualmente sua verdadeira forma.",
	["历史投影？"] = "Projeção histórica?",
	["历史旋涡"] = "Vórtice de História",
	["历史旋涡存在特效"] = "Efeito de Existência de Vórtice Histórico",
	["历史旋涡已被破坏，快转火阿蒙！"] = "O Vórtice Histórico foi destruído; mude rapidamente o fogo para Amon!",
	["历史明灯"] = "Farol Histórico",
	["历史是胜利者书写的谎言，但也是失败者最后的墓碑。"] = "A história é uma mentira escrita pelos vencedores, mas é também a lápide final dos perdedores.",
	["历史最佳"] = "Melhor de todos os tempos",
	["历史残页"] = "Fragmento Histórico",
	["历史渊源"] = "Origens Históricas",
	["历史的孔隙需要勇敢的人探索。"] = "As lacunas na história precisam de pessoas corajosas para serem exploradas.",
	["历史的潮流，将以罗塞尔为名！"] = "A maré da história terá o nome de Roselle!",
	["历史研究"] = "Pesquisa Histórica",
	["历史空隙"] = "Lacuna na história",
