	["女神可不管修阳台的事……"] = "A Deusa não se importa em consertar varandas...",
	["女神啊——他从高空坠落，没事吧？"] = "Deusa – ele caiu de tal altura, ele está bem?",
	["女神啊……你已经考虑十分钟了。"] = "Oh Deusa... você está pensando nisso há dez minutos.",
	["女神啊……你找了什么工作！"] = "Deusa... que tipo de trabalho você encontrou!",
	["女神啊……居然有这种事？他们的富有居然是装出来的吗？"] = "Deusa... existe realmente tal coisa? A riqueza deles era apenas uma fachada?",
	["女神啊……我向您忏悔……\r\n我应该不是唯一一个\r\n为两个女人心动的人吧？"] = "Oh Deusa... eu te confesso...\r\nEu não deveria ser a única\r\nque sentiu o coração palpitar por duas mulheres, certo?",
	["女神啊……救救我的孩子……半块黑面包也好……"] = "Deusa... salve meu filho... até meio pedaço de pão preto serve...",
	["女神啊……老师把店交给我的时候，我就说我做不到了……"] = "Ah, Deusa... quando a professora me entregou a loja, eu disse que não conseguiria...",
	["女神啊……请原谅我……"] = "Oh Deusa... por favor, me perdoe...",
	["女神啊……这么多活吗？"] = "Deusa... dá tanto trabalho?",
	["女神啊……那不是廷根富人区吗……怎么住到咱们这儿来了？"] = "Deusa... esse não é o bairro rico de Tingen... como ela acabou morando aqui?",
	["女神啊！你不要伸手！小心摔下来！"] = "Ó Deusa! Não entre em contato! Tenha cuidado para não cair!",
	["女神啊！听上去感觉比食堂强一百倍！ 咱们约个时间去一次吧！"] = "Ah, Deusa! Isso soa cem vezes melhor do que o refeitório! Vamos marcar um horário para ir lá uma vez!",
	["女神啊！她应该参加短跑比赛，而不是当送货员！"] = "Deusa! Ela deveria estar em uma corrida de velocidade, não trabalhando como mensageira!",
	["女神啊！怎么会变成这个样子？"] = "Deusa! Como isso acabou assim?",
	["女神啊！我忏悔……"] = "Ó Deusa! eu confesso...",
	["女神啊！菲尔，你怎么爬上去的？"] = "Ó Deusa! Phil, como você subiu até lá?",
	["女神啊！这两种食物居然真的有不同的口味？"] = "Deusa! Esses dois tipos de comida realmente têm sabores diferentes?",
	["女神啊！这真是令人吃惊！"] = "Deusa! Isto é verdadeiramente surpreendente!",
	["女神啊！食堂的面包能当凶器！ "] = "Deusa! O Pão do refeitório pode ser usado como arma!",
	["女神啊，他果然毫无责任心！"] = "Oh Deusa, ele realmente não tem senso de responsabilidade!",
	["女神啊，你小心点！别为了那只猫把自己搭进去！"] = "Deusa, tenha cuidado! Não se deixe matar por causa daquele gato!",
	["女神啊，你能不能先好好工作！"] = "Oh Deusa, por favor, faça seu trabalho corretamente!",
	["女神啊，你说这话真是拯救了这个街道。{{PlayerName}}，你有什么办法避开正面？"] = "Minha Deusa, você dizendo isso realmente salvou esta rua. {{PlayerName}}, você tem alguma maneira de evitar um confronto direto?",
	["女神啊，占卜师现在也是高危职业吗……我情愿报纸上多刊登些填字游戏，也不想看见这个……"] = "Oh Deusa, agora os adivinhos também exercem uma profissão de alto risco... Prefiro que o jornal publique mais palavras cruzadas do que veja isto...",
	["女神啊，去他的坚持！以后没有煎香肠卖的山我都不会来爬的！"] = "Deusa, dane-se essa persistência! Nunca mais subirei uma montanha se não houver linguiça frita à venda!",
	["女神啊，听听这说的是什么话？"] = "Deusa, ouça o que está sendo dito?",
	["女神啊，她果然早对我有意……"] = "Oh Deusa, ela realmente sente algo por mim há muito tempo...",
	["女神啊，好歹让我洗完衣服再停水啊……"] = "Oh Deusa, pelo menos deixe-me terminar de lavar a roupa antes de você cortar a água...",
	["女神啊，居然在这种地方遇见他，这太晦气了。"] = "Deusa, realmente encontrá-lo em um lugar como esse é muito azar.",
	["女神啊，居然在这种地方遇见她，这难道就是神给我指示，让我这次牢牢抓住她，不再放手？"] = "Deusa, realmente encontrá-la em um lugar como este, isso é um sinal de Deus, me dizendo para segurá-la firmemente desta vez e nunca mais soltá-la?",
	["女神啊，总有一天我要住到北区干净的地方去，再雇十个……不，至少二十个水仙花街出身的佣人从早到晚清理巡逻，绝对不允许任何一个牡蛎入侵我的生活！"] = "Deusa, um dia eu me mudarei para um lugar limpo no bairro Norte e contratarei dez... não, pelo menos vinte empregados da Rua Daffodil para limpar e patrulhar de manhã até a noite, e absolutamente não permitirei que nenhuma ostra invada minha vida!",
	["女神啊，感谢您多年来对我的庇佑。"] = "Deusa, obrigado por sua proteção ao longo dos anos.",
	["女神啊，我不会以后都吃不上午餐吧？"] = "Deusa, não poderei almoçar de agora em diante, não é?",
	["女神啊，我以为是无聊的谣传呢。"] = "Deusa, pensei que fosse apenas um boato chato.",
	["女神啊，我到底为什么要过这种恶臭的生活！"] = "Deusa, por que diabos eu tenho que viver essa vida nojenta!",
	["女神啊，我向您忏悔。"] = "Oh Deusa, eu confesso a Você.",
	["女神啊，我愿把全部的柔情都铺垫在她脚边！"] = "Deusa, estou disposto a colocar toda a minha ternura a seus pés!",
	["女神啊，我有选择困难症……"] = "Deusa, eu tenho paralisia de decisão...",
	["女神啊，我能否将你比作一个夏日？"] = "Deusa, devo compará-la a um dia de verão?",
	["女神啊，我该怎么办……？"] = "Deusa, o que devo fazer...?",
	["女神啊，我都快要决定答应他了！"] = "Deusa, estou quase decidindo concordar com ele!",
	["女神啊，用这副模样？您真会开玩笑。"] = "Deusa, nesta forma? Você realmente sabe brincar.",
	["女神啊，祈求我在贝克兰德的求学之旅一路顺利。"] = "Oh Deusa, rezo para que minha jornada de estudo em Backlund corra bem.",
	["女神啊，若你能够听到我的呼唤，让小艾琳回到我身边吧。"] = "Deusa, se você pode ouvir meu chamado, deixe a pequena Irene voltar para o meu lado.",
	["女神啊，请原谅我的\r\n自以为是……"] = "Oh Deusa, por favor, perdoe minha\r\nauto-justificação...",
	["女神啊，请垂怜！"] = "Oh Deusa, por favor, tenha misericórdia!",
	["女神啊，请您务必试试！"] = "Oh Deusa, por favor, você deve tentar!",
	["女神啊，请您护佑汉密尔顿家族，恩赐这可怜的小姑娘，让她得以享受难得的青春时光吧！"] = "Deusa, por favor, proteja a família Hamilton e conceda a esta pobre garota a chance de aproveitar sua rara juventude!",
	["女神啊，请让天上掉迪西馅饼吧——"] = "Oh Deusa, por favor, deixe as tortas Dicy caírem do céu—",
	["女神啊，请让安宁降临，\n　　让梦境包裹疲惫的灵魂，\n　　让黑夜庇护迷途的羔羊。"] = "Oh, Deusa, por favor, deixe a paz descer,\n\tDeixe os sonhos envolverem as almas cansadas,\n\tDeixe a noite fornecer abrigo para os cordeiros perdidos.",
	["女神啊，这么多订单，先送哪个呢？"] = "Deusa, tantos pedidos, qual devo entregar primeiro?",
	["女神啊，这些话语如同泉水一般在我的脑海中延绵不绝！"] = "Deusa, essas palavras são como uma fonte, fluindo infinitamente em minha mente!",
	["女神啊，这些话语如同泉水一般在我的脑海中延绵不绝，我真会为此痛苦而死……"] = "Deusa, essas palavras fluem incessantemente em minha mente como uma fonte; Eu poderia realmente morrer de dor por causa disso...",
	["女神啊，这已经是第三块了！"] = "Oh Deusa, esta já é a terceira peça!",
	["女神在上……可真吓人……"] = "Deusa acima... isso é realmente assustador...",
	["女神在上！玛莎！贝蒂！你们今早听见酒馆里人念报没？"] = "Pela Deusa! Marta! Betty! Você ouviu pessoas lendo jornal na taverna esta manhã?",
	["女神在上，保佑这个可怜人儿吧！"] = "Deusa do alto, abençoe esta pobre pessoa!",
	["女神在上，再继续下去，和虐待女性有什么区别？停止比赛吧！"] = "Deusa acima, se isso continuar, como é diferente de abusar de uma mulher? Pare a partida!",
	["女神在上，只有这世道变好，才能给她一个家"] = "Deusa do céu, só se este mundo melhorar poderei dar-lhe um lar.",
	["女神在上，我想做个香味蜡烛，帮助他获得安眠。"] = "Que a Deusa esteja conosco, quero fazer uma vela perfumada para ajudá-lo a dormir.",
	["女神在上，我有选择困难症……"] = "Deusa acima, tenho paralisia de decisão...",
	["女神在上，肯定是有人利用了教会。唉！我对不起艾琳，我这就回去！"] = "Deusa acima, alguém deve ter usado a Igreja. Suspirar! Eu falhei com Irene; Voltarei agora mesmo!",
	["女神在上，那可是詹姆斯！“终结者”！"] = "A Senhora está acima, esse é James! O 'Exterminador do Futuro'!",
	["女神将一个礼物赐给我。"] = "A Deusa concedeu-me um presente.",
	["女神庇佑"] = "Proteção da Deusa",
	["女神庇佑……请让我逃离那无边的噩梦……"] = "Deusa proteja... por favor, deixe-me escapar desse pesadelo sem fim...",
	["女神庇佑啊……"] = "Proteção da Deusa...",
	["女神庇佑我排到济贫院的名额，只要给我饭吃，我愿意挑绳絮。"] = "Que a Deusa me abençoe com um lugar no asilo. Enquanto eu tiver comida para comer, estou disposto a colher fibras de corda.",
	["女神庇佑！没想到我今天又看见了列车的蒸汽出现在这个站点。"] = "Louvado seja a Deusa! Eu não esperava ver o vapor do trem aparecer nesta estação novamente hoje.",
	["女神庇佑！谢谢你！"] = "Proteção da Deusa! Obrigado!",
	["女神庇佑，保佑这个可怜人儿吧！"] = "Deusa Proteção, abençoe esta pobre pessoa!",
	["女神庇佑，希望这种送上门的倒霉蛋再多一点吧。"] = "Proteção da Deusa, espero que haja mais desses tolos azarados que se entreguem à nossa porta.",
	["女神庇佑，愿她早日康复。"] = "Proteção da Deusa, que ela se recupere logo.",
	["女神庇佑，我在恶龙酒吧的斗邪恶比赛里赢了一张船票！很快我就要登船了。"] = "Proteção da Deusa, ganhei um ingresso de barco na Competição de Combate ao Mal no Bar do Dragão Maligno! Em breve embarcarei no navio.",
	["女神庇佑，我想试试买下那对绿宝石耳坠呢……虽然这实在要花一点钱。"] = "Que a Deusa me proteja, quero tentar comprar aquele par de brincos de esmeralda... embora realmente custe um pouco de dinheiro.",
	["女神庇佑，请赐予我的爱人一夜安眠吧，呵呵。"] = "Proteção da Deusa, por favor, conceda ao meu amante uma noite de sono, hehe.",
	["女神是包容的"] = "A Deusa é inclusiva",
	["女神没有回应我的祈祷，天一刻也不暗下来，我无法入眠。\n\n镇上的大家好像都不用睡觉，也许是我出了问题。\n\n其他地方也许就不一样了吧？"] = "A Deusa não respondeu à minha oração, o céu não vai escurecer por um momento, não consigo dormir. \n\n Todo mundo na cidade parece não precisar dormir, talvez algo esteja errado comigo. \n\n Talvez seja diferente em outro lugar?",
	["女神的凝望"] = "Olhar da Deusa",
	["女神的凝望、黑眼泪……三倍剂量够不够？"] = "Olhar da Deusa, Lágrimas Negras... uma dose tripla é suficiente?",
	["女神的眷顾呢？！"] = "Onde está o favor da Deusa?!",
	["女神的神国。"] = "O Reino de Deus da Deusa.",
	["女神看中你，令你获得了系统，也就是我本人，能够让你拥有更大的助力。"] = "A Deusa gostou de você, permitindo que você obtenha o sistema, que sou eu, e pode lhe dar uma ajuda maior.",
	["女神真的是这样说的吗……那我这就回去洗碗。"] = "A Deusa realmente disse isso... Então voltarei e lavarei a louça.",
	["女神眷顾！我觉得莫妮拉最近对我热情了点。真的……"] = "A Deusa me favorece! Sinto que Monila tem sido um pouco mais afetuosa comigo ultimamente. Realmente...",
	["女神职人员1"] = "Membro Feminino do Clero 1",
	["女神职人员2"] = "Membro Feminino do Clero 2",
	["女神！厄难与恐惧的女皇，求您！"] = "Deusa! Imperatriz da Calamidade e do Terror, eu imploro!",
	["女神，我、我来忏悔……"] = "Deusa, eu, eu vim confessar...",
	["女神，我祈求您让他受到应有的惩罚！"] = "Deusa, rezo para que você o deixe receber o castigo que merece!",
	["女神？这里是风暴之主的地盘！这样吧，我再加一点价，但你也得理解我的难处。我们各退一步！"] = "Deusa? Este é o território do Senhor das Tempestades! Que tal, vou aumentar um pouco o preço, mas você tem que entender minhas dificuldades. Vamos ambos dar um passo para trás!",
	["女祭司"] = "Alta Sacerdotisa",
	["女祭司-正位"] = "A Alta Sacerdotisa - Vertical",
	["女祭司-逆位"] = "A Alta Sacerdotisa - Invertida",
	["女祭司牌"] = "A Alta Sacerdotisa",
	["女职员"] = "Funcionária",
	["女职员1"] = "Funcionária 1",
	["女职员2"] = "Funcionária 2",
	["女职员们"] = "Funcionárias",
	["女警察"] = "Policial",
	["女警察1"] = "Policial 1",
	["女记者"] = "Repórter Feminina",
	["女贵族"] = "Mulher nobre",
	["女路人"] = "Transeunte feminina",
	["女郎"] = "Senhora",
	["女青年"] = "Mulher jovem",
	["女顾客"] = "Cliente feminina",
	["奴仆状态无法主动传送，请先解除状态"] = "Não é possível iniciar o teletransporte enquanto estiver no status de servo; remova o status primeiro.",
	["奴役之瓶"] = "Garrafa da Escravidão",
	["奶奶"] = "Avó",
	["奶奶对话"] = "Diálogo da vovó",
	["奶奶总是唱：“我会变成一只小猫，爬进你的摇篮。”"] = "A vovó sempre cantava: 'Vou virar um gatinho e rastejar até o seu berço'.",
	["奶奶朝向"] = "Orientação da vovó",
	["奶奶说，她这辈子最幸福的事，就是得到了那些种子。"] = "A vovó disse que a coisa mais feliz da vida dela foi conseguir aquelas sementes.",
	["奶奶说，这些南瓜的种子是很久很久以前，一位远游归来的朋友送给她的。那位旅人还带来了一种很特别的烈酒配方，现在全金秋湖都在卖呢！"] = "A vovó disse que essas sementes de abóbora lhe foram dadas há muito, muito tempo por uma amiga que voltou de uma viagem distante. Aquele viajante também trouxe uma receita muito especial de destilado, que agora é vendida em todo o Golden Autumn Lake!",
	["奶奶！您在天堂还好吗，有见到爷爷吗？"] = "Avó! Você está indo bem no céu? Você viu o vovô?",
	["奶奶，我好想吃你做的苹果派。"] = "Vovó, eu quero muito comer a torta de maçã que você fez.",
	["奶奶，是你回来了吗？"] = "Vovó, é você?",
	["奶奶，现在坐班的是叔叔……"] = "Vovó, quem está de plantão agora é o tio...",
	["奶奶，那边又在吵架……"] = "Vovó, eles estão discutindo ali de novo...",
	["奶油塔（临时）"] = "Torta de Creme (Temporária)",
	["奶油燕麦面包"] = "Pão De Aveia Cremoso",
	["奶牛猫"] = "Vaca gato",
	["奶盖禁止加班"] = "Milk Cap proíbe horas extras",
	["奶转火标记"] = "Cure a marca DPS",
	["奶酪摊摊主"] = "Dono de barraca de queijo",
	["奶香黄油"] = "Manteiga Cremosa",
	["她……她是虫子？"] = "Ela... ela é um inseto?",
	["她……她说黑荆棘总是会让她想起她的哥哥，所以就不进来了。"] = "Ela... ela disse que Blackthorn sempre a lembra do irmão, então ela não apareceu.",
	["她、她收下了！她说她也注意我很久了！"] = "Ela, ela aceitou! Ela disse que também está me notando há muito tempo!",
	["她、她是怎么突破学派的防线进来的？"] = "Como, como ela rompeu as defesas da escola para entrar?",
	["她、她是怎么突破学院的防线进来的？"] = "Como, como ela rompeu as defesas da academia para entrar?",
	["她一定对你很重要吧？"] = "Ela deve ser muito importante para você, certo?",
	["她一直念叨六只鸽子。 "] = "Ela continua resmungando sobre seis pombos.",
	["她丈夫报警了，警察到现在也没查到下落。<P_Heart>（啐了一口）</>也是一帮没用的！"] = "O marido dela chamou a polícia, mas ainda não encontraram vestígios dela. <P_Heart> (Cospe) </> Um monte de gente inútil também!",
	["她丈夫报警了，警察到现在也没查到下落。（啐了一口）也是一帮没用的！"] = "O marido dela chamou a polícia, mas eles ainda não encontraram nenhuma pista. (cospe) Um bando de gente inútil!",
	["她丈夫这么久了还没回来，不会是……"] = "O marido dela não volta há tanto tempo, será que...",
	["她不再只是谁的附属，每一个念头都属于她自己。"] = "Ela não é mais um apêndice de ninguém; cada pensamento pertence somente a ela.",
	["她不在这里？四处找找看吧。"] = "Ela não está aqui? Vamos dar uma olhada.",
	["她不忙的时候，就看看书，在纸上写写画画。"] = "Quando não estava ocupada, ela lia livros e escrevia ou desenhava no papel.",
	["她不是去见一个人……她是……"] = "Ela não foi ver ninguém... ela é...",
	["她不是故意这么做的，她只是不太清醒。"] = "Ela não fez isso de propósito; ela simplesmente não é muito lúcida.",
	["她临死前拉着我的手说——她这辈子最后悔的，不是相信了占卜。"] = "Antes de morrer, ela segurou minha mão e disse: a coisa que ela mais se arrependeu na vida foi não acreditar em adivinhação.",
	["她为世界编织美丽，却独自走向永恒的黑夜。"] = "Ela tece beleza para o mundo, mas caminha sozinha na noite eterna.",
	["她为我讲述了一个爱情故事，以弥补我情感经历上的空缺——解释一下，我不认为这是缺陷。"] = "Ela me contou uma história de amor para compensar a lacuna em minha experiência emocional — para explicar, não acho que isso seja uma falha.",
	["她为每个人安排了不同的死因。"] = "Ela organizou uma causa de morte diferente para cada um.",
	["她主动和我搭话！"] = "Ela tomou a iniciativa de falar comigo!",
	["她之前挺慷慨的，但和家族断绝关系后就……唉。"] = "Ela costumava ser bastante generosa, mas depois de romper os laços com a Família, ela... suspirou.",
	["她也很幸运……我很快就病死了，她被教会带走……后来，市场贩卖肉类的好心夫妻收养了她。"] = "Ela também tem muita sorte... Morri de doença logo depois, e ela foi levada pela Igreja... Mais tarde, um simpático casal que vendia carne no mercado a adotou.",
	["她也是为守护廷根牺牲的，愿她在黑夜的庇佑中获得安眠。"] = "Ela também se sacrificou para proteger Tingen. Que ela encontre o sono sob a proteção da Deusa da Noite Eterna.",
	["她也是非凡者吗？"] = "Ela também é uma Beyonder ?",
	["她亲生爸妈也是疯子！"] = "Seus pais biológicos também são loucos!",
	["她什么时候回来？"] = "Quando ela estará de volta?",
	["她什么都没说，但我看见了，相亲的地点是老维尔餐厅。"] = "Ela não disse nada, mas eu vi, o local do encontro às cegas é o restaurante Old Will's.",
	["她今天美得像夜晚的星辉……"] = "Ela está tão linda quanto a luz das estrelas da noite de hoje...",
	["她从不只是站在台上。她会走进人群，像一阵风掠过你的身侧，而你甚至来不及捕捉她的温度……只余下一道眼神，让你整晚都在怀疑：刚才那一瞥，究竟是不是给你的。"] = "Ela nunca fica apenas no palco. Ela entra na multidão como uma rajada de vento passando por você, e você nem tem tempo de sentir o calor dela... deixando apenas um olhar que faz você se perguntar a noite toda: aquele olhar foi realmente feito para você?",
	["她从哪儿来的？"] = "De onde ela veio?",
	["她从小喜欢齿轮、发条、轴承，立志做一名蒸汽机械师。"] = "Desde criança gosta de engrenagens, molas e rolamentos e está decidida a ser mecânica a vapor.",
	["她从小懂得孝顺老父亲，爱护弟弟，心疼妈妈，有的时候，又特别正直，显得有点傻，唉。"] = "Desde jovem ela soube ser filial com o velho pai, cuidar do irmão mais novo e amar a mãe. Às vezes, ela também é particularmente ereta, parecendo um pouco boba, suspiro.",
	["她从未见过光，但她知道，光一定存在。因为妈妈说过，世界上最温暖的东西，就是太阳。"] = "Ela nunca tinha visto luz, mas sabia que a luz devia existir. Porque mamãe disse que a coisa mais quente do mundo é o sol.",
	["她以前很喜欢来这里，能挑上一整个下午。只是我当时太年轻，没有耐心等待……"] = "Ela adorava vir aqui e podia passar uma tarde inteira escolhendo um. É que eu era muito jovem naquela época e não tinha paciência para esperar...",
	["她们不都住在纪念碑广场那边吗？罗伯特那家伙不尴尬吗？"] = "Os dois não moram na Memorial Square? Isso não é estranho para Robert?",
	["她们可以上一秒手挽着手说笑，也可以下一秒就开始互相扯对方的头发！"] = "Eles podem estar de mãos dadas e rir em um segundo e começar a puxar o cabelo um do outro no próximo!",
	["她们看到葡萄架下有一滩血，吓得跑了。"] = "Eles viram uma poça de sangue sob a treliça de uvas e fugiram com medo.",
	["她们都给自己起了昵称，大赛琳娜，小赛琳娜，蓝色赛琳娜……"] = "Todas elas se deram apelidos: Grande Selena, Pequena Selena, Blue Selena...",
	["她们隐瞒了……"] = "Eles se esconderam...",
	["她会好起来的。她肯定会的。\n等我们攒够钱，我就带她去豪森医生的诊所。"] = "Ela vai melhorar. Ela definitivamente irá. \n Assim que economizarmos dinheiro suficiente, vou levá-la à clínica do Dr. Horsen.",
	["她会愚一下，然后笑出来，说：“苏茜，你什么时候学会心理咨询了？”"] = "Ela agia como uma tola, depois ria e dizia: \"Susie, quando você aprendeu a dar aconselhamento psicológico?\"",
	["她会愣一下，然后笑出来，说：“苏茜，你什么时候学会心理咨询了？”"] = "Ela ficará atordoada por um momento, depois rirá e dirá: “Susie, quando você aprendeu aconselhamento psicológico?”",
	["她会收下吗？"] = "Ela aceitará isso?",
	["她会说什么吗？"] = "Ela diz alguma coisa?",
	["她似乎能用言语操控他人的情绪。不像是普通的社交能力，是非凡能力。难道是刺客途径教唆者？"] = "Ela parece ser capaz de usar palavras para manipular as emoções dos outros. Não parece uma habilidade social comum; é uma habilidade Beyonder. Poderia ser o Instigador do Assassino Caminho?",
	["她倒下了，又站起来……不像是假的。"] = "Ela caiu e se levantou de novo... não parece falso.",
	["她像不像一朵雏菊？"] = "Ela não parece uma margarida?",
	["她像只流浪猫，肮脏又危险，不知道哪天就会腐烂在下水道里。"] = "Ela é como um gato de rua, sujo e perigoso. Quem sabe quando ela apodrecerá nos esgotos.",
	["她出现的原因"] = "A razão de sua aparição",
	["她刚刚几乎灵性枯竭，现在状态太差了……还是先帮她恢复一下吧。"] = "Ela estava quase no ponto de espiritualidade exaustão agora; a condição dela é muito ruim... Eu deveria ajudá-la a se recuperar primeiro.",
	["她动手了！"] = "Ela fez um movimento!",
	["她半年前患上了急性血液病，因为没有足够的费用治疗，不久后就去世了。"] = "Ela sofria de leucemia aguda há seis meses e, como não havia dinheiro suficiente para o tratamento, faleceu pouco depois.",
	["她半年前患上了急性血液病，因为没有足够的费用治疗，不就后就去世了。"] = "Ela sofria de leucemia aguda há seis meses e, como não havia dinheiro suficiente para o tratamento, faleceu pouco depois.",
	["她去世后，我跟梅丽莎他们也时不时会来教堂祈祷，我算得上女神真正的信徒。"] = "Depois que ela faleceu, Melissa e eu ainda íamos à catedral para orar de vez em quando. Posso ser considerada uma verdadeira crente na Deusa.",
	["她只会做一件事——歪着头看着您，问一句“哥哥，你今天累不累呀”。"] = "Ela só faz uma coisa: inclina a cabeça, olha para você e pergunta: “Irmão, você está cansado hoje?”",
	["她只是普通人，让她服用非凡药剂，会不会有风险？"] = "Ela é apenas uma pessoa comum, haverá riscos se ela tomar Beyonder poções?",
	["她叫什么名字？"] = "Qual o nome dela?",
	["她叫苏茜，我的助手，也是一位女士。"] = "O nome dela é Susie, minha assistente e também uma senhora.",
	["她可能会昏睡几分钟，但没别的问题。不过她的神秘学老师太不靠谱了，居然没告诉她基本的禁忌事项。"] = "Ela pode dormir profundamente por alguns minutos, mas não há outros problemas. No entanto, seu professor de ocultismo não é confiável; ele nem mesmo contou a ela os tabus básicos.",
	["她听说你是位“贵族诗人”，特意抄了诗集，觉得这样才配得上你的身份。"] = "Ela ouviu que você era um ‘nobre poeta’ e copiou especificamente a coleção de poesia, pensando que seria digna de seu status.",
	["她告诉他，这个小镇看似普通，其实它并不存在于现实世界中。它只是一个虚影、一个幻梦。"] = "Ela disse a ele que a cidade, embora parecesse comum, na verdade não existia no mundo real. Era apenas um fantasma, um sonho.",
	["她告诉我，这些东西不是用来对付普通罪犯的。"] = "Ela me disse que essas coisas não foram feitas para lidar com criminosos comuns.",
	["她和他、他和她、<Hide stylename=\"Transparent\" id=\"#161\">她和她、他和他、</>\n缠绵悱恻的爱情故事，尽在廷根大剧院！\n\n\n<Note_Normal_HW>**的，谁把后面的字涂掉了，我就爱看这个！</>\n\n<Note_Normal_HW>算了吧，老兄，这附近还有小屁孩呢，而且你真有钱去买廷根大剧院的票？</>\n\n<Note_Normal_HW>说得好像附近的小屁孩有几个认识字一样！</>"] = "Ela e ele, ele e ela, <Hide stylename=\"Transparent\" id=\"#161\"> ela e ela, ele e ele, </> \n uma comovente história de amor, tudo no Grande Teatro Tingen! \n \n \n <Note_Normal_HW> **'s, quem apagou as palavras atrás? Eu adoro assistir isso! </> \n \n <Note_Normal_HW> Esqueça, irmão, há crianças pequenas por perto e você realmente tem dinheiro para comprar um ingresso para o Grande Teatro de Tingen? </> \n \n <Note_Normal_HW> É como se qualquer uma das crianças próximas soubesse ler! </>",
	["她和他、他和她、她和她、他和他、缠绵悱恻的爱情故事，尽在廷根大剧院！"] = "Ela e ele, ele e ela, ela e ela, ele e ele - histórias de amor persistentes e comoventes, todas no Grande Teatro de Tingen!",
	["她和儿子一起租住在这里十多年了。据附近的邻居说，已经超过一周没见到他们了。"] = "Ela e o filho moram aqui há mais de dez anos. Segundo vizinhos, eles não são vistos há mais de uma semana.",
	["她和山姆在一起是因为——"] = "Ela está com Sam porque—",
	["她和朋友聊天也张口闭口提到“亲爱的”……可我问她什么她都不说！"] = "Ela fica dizendo \"querido\" sempre que fala com as amigas... mas não me conta nada quando eu pergunto!",
	["她哪天不是故意的？上次她从我身边经过，就碰了我一下袖子，我回去三天没舍得洗那件衣服。"] = "Quando ela não está fazendo as coisas de propósito? Da última vez que ela passou por mim e tocou minha manga, não tive coragem de lavar aquela camisa por três dias.",
	["她唱着睡吧，睡吧，死神的羽翼垂下之时，我们收获美梦。"] = "Ela cantou: 'Durma, durma, quando as asas do Deus da Morte descerem, colheremos bons sonhos.'",
	["她在喊……她在喊救命！我听见她在喊你的名字！"] = "Ela está gritando... ela está gritando por socorro! Eu a ouvi chamando seu nome!",
	["她在夜色里诞生，打了两个响指就落成这座小镇。"] = "Ela nasceu durante a noite e, com dois estalar de dedos, esta pequena cidade foi construída.",
	["她在躲谁？"] = "De quem ela está se escondendo?",
	["她大概到我腰这么高，金头发，有一双漂亮的大眼睛。"] = "Ela é quase tão alta quanto a minha cintura, com cabelos dourados e um par de lindos e grandes olhos.",
	["她失踪时大部分笔记都不见了，但我还留着一页，你要看看吗？"] = "A maioria das anotações dela desapareceu quando ela desapareceu, mas ainda tenho uma página sobrando, quer ver?",
	["她好像……"] = "Ela parece...",
	["她好像动了动……是错觉吗？"] = "Ela parecia se mover... era uma ilusão?",
	["她好像和家人走散了？时间这么晚了，先找到她问问吧。"] = "Ela se separou da família? É tão tarde, vamos encontrá-la e perguntar.",
	["她好像在说：“苏茜，我需要一个人待一会儿。你能帮我看着门吗？”"] = "Ela parecia estar dizendo: 'Susie, preciso ficar um pouco sozinha. Você pode me ajudar a vigiar a porta?",
	["她好像很专注……还是过去跟她打个招呼吧。"] = "Ela parece muito focada... Eu deveria ir até ela e cumprimentá-la.",
	["她好像很专注，过去跟她打个招呼吧。"] = "Ela parece muito focada, vá até ela e diga olá para ela.",
	["她家就在旁边这栋楼上吧？"] = "A casa dela fica no prédio aqui ao lado, certo?",
	["她对每个人说：\"这是别人给我的，现在它也是你的了。\""] = "Ela disse a todos: “Isto me foi dado por outra pessoa e agora é seu também”.",
	["她对每个人说：“这是别人给我的，现在它也是你的了。”"] = "Ela disse a todos: “Isso me foi dado por alguém e agora é seu também”.",
	["她将身躯化为石像，伫立在此，永远守护着她造就的丰饶之地。"] = "Ela transformou seu corpo em uma estátua de pedra, ficando aqui, guardando para sempre a terra fértil que ela criou.",
	["她尖叫着，撕扯着自己的头发，虫子一样翻滚在地。"] = "Ela grita, arrancando os próprios cabelos, rolando no chão como um verme.",
	["她就在附近上班，她好像在一家……安保公司？对，黑荆棘。"] = "Ela trabalha aqui perto, acho que em uma... empresa de segurança? Sim, Blackthorn.",
	["她就是“专家”？"] = "Ela é a \"especialista\"?",
	["她就是内务大臣，梅。每年我们王国都只过一次生日，主角都是她。"] = "Ela é a Ministra da Administração Interna, maio. Todos os anos nosso reino comemora apenas um aniversário, e ela é sempre a protagonista.",
	["她就是小黛西？我好像见过她……在黛西小姐的循环空间中，她拿着雏菊花奔跑在路上，但……"] = "Ela é a Pequena Margarida? Acho que a vi... no espaço circular da Srta. Daisy, ela estava correndo na estrada segurando margaridas, mas...",
	["她就是闪电莉莉，“闪电速递”头牌送货员！"] = "Ela é Lightning Lily, a principal entregadora do 'Lightning Express'!",
	["她已经离去，但银哨会一直唱着悠扬的歌，祝愿每一个心怀守护理想的人，美梦成真。"] = "Ela partiu, mas o apito prateado sempre cantará sua canção melodiosa, desejando que todos que possuem um sonho de proteção vejam seus sonhos realizados.",
	["她平时很听话的。她有位朋友，今天约了她出门。"] = "Ela geralmente é muito obediente. Ela tem uma amiga que planejou sair com ela hoje.",
	["她并没有使用匕首“自杀”，锁门也不是关键线索，<P_Yellow>导致她“死亡”的直接因素是房间里的仪式魔法</>……"] = "Ela não usou a adaga para “cometer suicídio” e trancar a porta não era uma pista importante. <P_Yellow> O fator direto que causou sua 'morte' foi o Ritual de Magia na sala </>...",
	["她应该去寻找咖啡馆去了。"] = "Ela deveria ter ido procurar um café.",
	["她引诱孩子们的能力，应该是靠那根笛子释放的。"] = "Sua capacidade de atrair crianças deve ser liberada através daquela flauta.",
	["她往这边走了？"] = "Ela caminhou por aqui?",
	["她很不幸，有我这样的妈妈，让她在下街的垃圾堆里长大。"] = "Ela é muito infeliz por ter uma mãe como eu, deixando-a crescer nas pilhas de lixo da Lower Street.",
	["她很厉害，很坚强，我输得心服口服。"] = "Ela é muito poderosa e muito forte. Eu perdi e aceito isso de todo o coração.",
	["她很喜欢我送她的戒指，每天都戴着到处炫耀，劝都劝不住。"] = "Ela realmente gostou do anel que eu dei a ela. Ela o usa em todos os lugares para exibi-lo; Eu não posso nem pará-la.",
	["她很瘦，衣服又破又旧，连双鞋都没穿，这样的孩子在铁十字街太多了。我当时急着卖货，确实没细看。"] = "Ela era muito magra, suas roupas estavam esfarrapadas e velhas e ela nem usava sapatos. Há muitas crianças assim na Rua Cruz de Ferro. Eu estava com pressa para vender meus produtos na época, então não olhei com atenção.",
	["她很聪明，才五岁，就会拾走市场的猪膀胱，卖给苦酒贩子……也会细心地帮我分类垃圾，把白色的废布料送去造纸厂，那能卖出更高的价钱。"] = "Ela é muito inteligente. Com apenas cinco anos, ela recolhia bexigas de porco no mercado para vender aos vendedores ambulantes de vinho amargo... Ela também me ajudava cuidadosamente a separar o lixo, enviando os restos de tecido branco para a fábrica de papel, pois poderiam ter um preço mais elevado.",
	["她怎么了？"] = "O que aconteceu com ela?",
	["她怎么会知道这些？"] = "Como ela saberia disso?",
	["她怎么每天都站在这里看船，脖子上还戴着婚戒。"] = "Por que ela fica aqui observando os navios todos os dias, ainda usando sua aliança de casamento?",
	["她怎么每天都站在这里看船，脖子上还戴着那条项链。"] = "Por que ela fica aqui todos os dias observando os navios, usando aquele colar no pescoço?",
	["她怎么说？"] = "O que ela disse?",
	["她总来买小束的、颜色最亮的花，说要摆在桌子上，“给枯燥的公文也晒晒太阳”。她的话呀，像小鸟一样，又轻快又多，听着都让人高兴。"] = "Ela sempre vem comprar pequenos buquês das flores mais brilhantes, dizendo que quer colocá-los em sua mesa para “deixar os enfadonhos documentos oficiais absorverem um pouco de sol”. Suas palavras são como passarinhos, leves e numerosas; fica feliz só de ouvir.",
	["她想和我一起生活，我想和她一起承担生活的狂风大雨。"] = "Ela quer morar comigo e eu quero suportar as tempestades da vida com ela.",
	["她想赞助你一笔零花钱，又怕你不好意思收。"] = "Ela quer patrocinar algum dinheiro para você, mas tem medo que você fique com vergonha de aceitá-lo.",
	["她憎恨命运"] = "Ela odeia o destino.",
	["她所经过的地方，一切都可靠而恰到好处。"] = "Por onde ela passa, tudo é confiável e na medida certa.",
	["她才十六岁，刚才又避开我溜出家门，我好担心，她是不是跟什么坏人来往了？"] = "Ela tem apenas dezesseis anos e acabou de sair de casa novamente. Estou tão preocupado; ela tem se associado com alguma pessoa má?",
	["她才十四岁，刚才又避开我溜出家门，我好担心，她是不是跟什么坏人来往了？"] = "Ela tem apenas quatorze anos. Ela escapou de casa novamente mais cedo e estou muito preocupado. Ela está se associando com algumas pessoas más?",
	["她扔下一句话，说“这都是什么烂叶子！”，带着她那颗高傲的心走啦。"] = "Ela lançou uma frase, dizendo “Que tipo de folhas podres são essas!”, e saiu com o coração orgulhoso.",
	["她把这些都记在心里，想着：总有一天，我会摸到太阳的。"] = "Ela guardou tudo isso em seu coração, pensando: Um dia tocarei o sol.",
	["她抿着嘴，目光十分警惕，她不敢与你争夺这里的东西，却又舍不得放弃。"] = "Ela franziu os lábios, seu olhar muito vigilante. Ela não se atrevia a competir com você pelas coisas aqui, mas também não suportava desistir delas.",
	["她拒绝我的时候，神情很平静，连一句客套话都没有……"] = "Quando ela me rejeitou, sua expressão era muito calma, sem sequer uma frase educada...",
	["她救了你。"] = "Ela salvou você.",
	["她无疑是全场最引人注目的人。五官精致得近\n乎不真实，灰绿色的眼眸带着漫不经心的疏离\n——像在享受这场舞会，又像在冷眼旁观所有\n人。 "] = "Ela é sem dúvida a pessoa mais atraente da sala. Suas feições são tão lindas que são quase \n irreais, e seus olhos verde-acinzentados carregam um distanciamento casual \n - como se ela estivesse gostando do baile, mas também observando todos friamente do lado de fora. \n",
	["她无疑是全场最引人注目的人。五官精致得近乎不真实，灰绿色的眼眸带着漫不经心的疏离——像在享受这场舞会，又像在冷眼旁观所有人。"] = "Ela era sem dúvida a pessoa mais atraente da sala. Suas feições eram lindas a ponto de serem irreais, e seus olhos verde-acinzentados carregavam um distanciamento casual – como se ela estivesse aproveitando o baile, mas também observando a todos com fria indiferença.",
	["她是一位性格非常爽朗奔放的女士，也喜欢开玩笑，听说她还有一个可爱的儿子。"] = "Ela era uma senhora muito alegre e de espírito livre que também adorava brincar. Ouvi dizer que ela tinha um filho fofo.",
	["她是一名尝试晋升的非凡者，然而现场一片混乱，房门紧锁，贝茨太太却不见踪迹……"] = "Ela estava Beyonder tentando avançar, mas a cena está um caos completo, a porta está trancada e a Sra. Bates não foi encontrada em lugar nenhum...",
	["她是个好人。虽然她总是一副冷冰冰的样子，但她从不像大地母神教会的那帮人一样，真的阻止我做研究。"] = "Ela é uma boa pessoa. Apesar de sempre ter um olhar frio, ela nunca me impede de fazer pesquisas como aquela galera da Igreja Mãe Terra.",
	["她是个怪胎！"] = "Ela é uma aberração!",
	["她是个疯子！"] = "Ela é uma louca!",
	["她是个疯子，经常在角落里嘟囔一些毛骨悚然的话，还会无缘无故尖叫，连黑夜女神的祈祷词都无法令她安静哪怕十分钟。"] = "Ela é uma louca que muitas vezes murmura coisas assustadoras pelos cantos e grita sem motivo. Mesmo a oração da Deusa da Noite Eterna não consegue mantê-la quieta nem por dez minutos.",
	["她是个骗子"] = "Ela é uma mentirosa",
	["她是个魔鬼！"] = "Ela é um demônio!",
	["她是什么"] = "O que ela é",
	["她是子爵夫人，是真正的贵族，是为廷根带来新生的使者。"] = "Ela é a Viscondessa, uma verdadeira nobre e a mensageira que trouxe nova vida a Tingen.",
	["她是工厂的一名女工，工厂的少爷邀请她去参加舞会。"] = "Ela é operária da fábrica e o jovem patrão da fábrica a convidou para ir ao baile.",
	["她是第一个叫我名字的人，不嫌弃我是赠品的人。"] = "Ela é a primeira pessoa a chamar meu nome, aquela que não se importou que eu fosse um presente grátis.",
	["她是谁？"] = "Quem é ela?",
	["她是谁？为什么认为是她在报复你们？"] = "Quem é ela? Por que você acha que ela está se vingando de você?",
	["她是重振家族荣光的明星！本不是我们可以接近的天才！"] = "Ela é uma estrela que irá restaurar a glória da Família! Ela é um gênio que nunca deveríamos abordar!",
	["她是镇上最聪明的女孩，就是总爱说些奇怪的话。"] = "Ela era a garota mais inteligente da cidade, sempre adorou dizer coisas estranhas.",
	["她是？"] = "Quem é ela?",
	["她曾是上流社会的宠儿，可自从她的丈夫破产后……唉，我们这寒酸地方如今成了她的归宿。"] = "Ela já foi a queridinha da alta sociedade, mas desde que seu marido faliu... suspiro, nossa casinha miserável agora se tornou seu lar.",
	["她最后晋升到了序列5，在一场对叛徒的围猎中牺牲。"] = "Ela finalmente avançou para Sequência 5 e se sacrificou na caça a um traidor.",
	["她最后的心声"] = "Sua última voz interior",
	["她最近总抱怨夜班和皮肤差，该找个能和她轮班的同事。"] = "Ela tem reclamado de turnos noturnos e problemas de pele ultimamente; ela deve encontrar um colega que possa alternar os turnos com ela.",
	["她有一个好赌的父亲，让家里欠了很多钱，她只好自己出来打工……"] = "Ela tem um pai jogador que fez com que a família devesse muito dinheiro, então ela mesma teve que sair para trabalhar...",
	["她有一位女性朋友，非要在本该来望弥撒的时间邀请她参加约会，我当然没有允许。"] = "Ela tem uma amiga que fez questão de convidá-la para um encontro no horário em que deveria ir à missa, o que naturalmente não permiti.",
	["她有一颗晨曦般温暖的心。\n\n道恩"] = "Ela tem um coração tão quente quanto o sol da manhã.\n\nDunn",
	["她有很多、很多的故事，要告诉你。"] = "Ela tem muitas, muitas histórias para contar.",
	["她来了！哼哼，小偷、骗子、撒谎精！到拳击台上也一样！"] = "Ela está aqui! Hmph, ladrão, vigarista, mentiroso! É a mesma coisa até no ringue de boxe!",
	["她来码头接她的丈夫。"] = "Ela veio ao cais buscar o marido.",
	["她死过一次，又活了回来。 她以为自己已经不怕任何东西了。\n但她怕。 她怕的东西只剩一件—— 再次失去。\n所以她握着镰刀，握着黑暗，握着一切可以握住的东西， 只是为了护住那一点点光， 哪怕那点光已经变成了她看不懂的形状， 她也不肯放手。\n黑暗中人，往往比谁都清楚， 光长什么样子。"] = "Ela morreu uma vez e voltou à vida. Ela pensou que não tinha mais medo de nada. \n Mas ela está com medo. Só resta uma coisa que ela teme: perdê-lo novamente. \n Então ela segura a foice, segura a escuridão, segura tudo o que pode segurar, só para proteger aquele pouquinho de luz, mesmo que essa luz tenha se transformado em uma forma que ela não consegue entender, ela se recusa a soltá-la. \n As pessoas na escuridão muitas vezes sabem melhor do que ninguém como é a luz.",
	["她没告诉你们她叫什么吗？感觉她在有意帮助我们，但……不愿意暴露身份？"] = "Ela não te disse o nome dela? Parece que ela está nos ajudando intencionalmente, mas... ela não quer revelar sua identidade?",
	["她没有恶意，又或许……"] = "Ela não tem malícia, ou talvez...",
	["她没有说客套话，是不是就代表我在她心里并不一般……"] = "Se ela não disse nada educado, isso significa que não sou qualquer um para ela...",
	["她没说茶会的地点，只留下了这枚胸针。"] = "Ela não disse onde foi a festa do chá, apenas deixou este broche para trás.",
	["她消失了……"] = "Ela desapareceu...",
	["她牺牲在一次任务中，和阿诺德的爸爸一样，也跟许多值夜者一样。"] = "Ela se sacrificou durante um missão , assim como o pai de Arnold, e como muitos outros Vigias Noturnos .",
	["她现在属于贝克兰德教区，值夜者不能随便离开自己辖区，这你应该清楚。"] = "Ela agora pertence à Diocese de Backlund. Vigias Noturnos não pode deixar sua jurisdição à vontade; você deveria saber disso.",
	["她甜美的笑容却像淬了蜜的刀，危险而美丽。"] = "Seu doce sorriso é como uma faca mergulhada em mel, perigosa e bonita.",
	["她的“完美”是建立在对自我的撕裂之上的。如果你接受这份“同化”，你将永远迷失在镜中，成为她意识的碎片之一。"] = "Sua 'perfeição' é construída sobre a destruição de si mesma. Se você aceitar essa 'assimilação', você se perderá para sempre no espelho, tornando-se um dos fragmentos de sua consciência.",
	["她的丈夫和孩子在几年前的战争中去世了，只剩下她和那条叫劳拉的狗，去哪儿都要一起。"] = "O marido e o filho morreram na guerra há alguns anos. Agora são só ela e aquela cadela chamada Laura, e elas vão a todos os lugares juntas.",
	["她的丈夫牺牲后，她致力于推动退伍士兵的福利事业，也成为了俱乐部的重要成员……"] = "Depois que seu marido se sacrificou, ela se dedicou a promover o bem-estar dos soldados aposentados e também se tornou um membro importante do clube...",
	["她的光芒不在于珠宝与华服，而在于那颗想要守护正义的心。"] = "Seu esplendor não reside nas joias e nas roupas finas, mas naquele coração que deseja zelar pela justiça.",
	["她的呼吸声还没有停，她还在等我们一家团聚……"] = "Sua respiração ainda não parou, ela ainda está esperando nossa família se reunir...",
	["她的声音很平静，像是在讲睡前故事。"] = "Sua voz é muito calma, como se estivesse contando uma história para dormir.",
	["她的成绩很好，很有希望。学派的老师建议她去考贝克兰德技术大学。"] = "Suas notas são muito boas e ela tem muita esperança. A professora sugeriu que ela fizesse o exame para a Backlund Technical University.",
	["她的梦里一片荒芜……"] = "Seu sonho é um deserto...",
	["她的灵破碎不堪，似乎经历过……一些很痛苦的事情。"] = "Seu espírito está despedaçado; parece que ela passou por... algumas coisas muito dolorosas.",
	["她的爱恨"] = "Seu amor e ódio",
	["她的爱，她的血，她曾引以为傲的理智"] = "Seu amor, seu sangue e a sanidade da qual ela uma vez se orgulhou.",
	["她的爸妈把她丢在了救济院门口！"] = "Os pais dela a abandonaram na entrada do orfanato!",
	["她的眼神没有杀意。尖叫太刻意，像是故意制造恐慌。"] = "Não há intenção de matar em seus olhos. O grito foi muito deliberado, como se ela estivesse criando pânico intencionalmente.",
	["她的离开让我的心都碎了。人活着的意义到底是什么？"] = "Sua partida partiu meu coração. Qual é o significado de estar vivo?",
	["她的花一夜开到天明 但待到白昼睁开了眼睛……"] = "Suas flores florescem durante a noite até o amanhecer, mas quando a luz do dia abre seus olhos...",
	["她的记忆和情绪破碎了，散落在那些碎片里。"] = "Suas memórias e emoções estão despedaçadas, espalhadas entre esses fragmentos.",
	["她看透了世界的真相，她告诉了我，可我总是差一点才能领悟……"] = "Ela viu através da verdade do mundo, ela me disse, mas estou sempre um pouco longe de compreendê-la...",
	["她真是我们的榜样，我会一直支持她。"] = "Ela é verdadeiramente nosso modelo. Eu sempre irei apoiá-la.",
	["她真的好美啊……而且那些香水，闻起来确实不一样，她最后究竟会接受哪位伯爵呢？"] = "Ela é realmente tão linda... e esses perfumes realmente têm um cheiro diferente. Qual Earl ela eventualmente aceitará?",
	["她短头发，大概……大概跟你差不多高。"] = "Ela tem cabelo curto, quase tão alto quanto você.",
	["她笑着在公园的各个角落里，准确找到了躲藏的孩子们。阳光所到之处，到处洋溢着纯真的欢笑。"] = "Ela riu ao encontrar com precisão as crianças escondidas em todos os cantos do parque. Onde quer que a luz do sol chegasse, risadas inocentes transbordavam.",
	["她笑着在公园的各个角落里，准确找到了躲藏的小孩。"] = "Ela sorriu ao encontrar com precisão as crianças escondidas em todos os cantos do parque.",
	["她经常说些诡异的话，太可怕了！"] = "Ela costuma dizer coisas estranhas, é muito assustador!",
	["她给一个卖鱼的说他妻子会好起来——牌面明明是逆位星币五，贫困和疾病。她偏说什么“两个人依偎着就能等到春天”。这不是骗人是什么？"] = "Ela disse a um peixeiro que sua esposa iria melhorar – a carta era claramente o Cinco de Ouros invertido, pobreza e doença. Ela insistiu em dizer “duas pessoas apoiadas uma na outra podem esperar pela primavera”. Se isso não é uma farsa, o que é?",
	["她给了我一个能做实验的地方，让我可以继续做研究。"] = "Ela me deu um lugar para fazer experimentos, permitindo-me continuar minha pesquisa.",
	["她继承的是来自她外祖父的非凡特性和神奇物品，她的外祖父该不会是一个大盗吧？"] = "Ela herdou o Característica de Beyonder e item místico de seu avô. Poderia seu avô ter sido um mestre ladrão?",
	["她肯定是受女神的眷顾保佑，才能安稳地工作到退休。"] = "Ela deve ser protegida pelo favor da Deusa para poder trabalhar de forma constante até a aposentadoria.",
	["她肯定是爱上我了……才会对我说这么多自己家里的事。"] = "Ela deve ter se apaixonado por mim... por isso me contou tanto sobre sua família.",
	["她背后的那架小飞机，就是她在剧组里帮我设计的道具之一。"] = "O pequeno avião atrás dela é um dos adereços que ela me ajudou a projetar para a equipe de filmagem.",
	["她行于绯红的月轮之下，将安眠赐予劳苦奔波的魂灵。"] = "Ela caminha sob a lua carmesim, proporcionando sono às almas que trabalham e vagam.",
	["她衣服上总沾着皮屑，恐怕只有成年男子有那样大块的皮屑！多脏的人啊！"] = "Suas roupas estão sempre cobertas de escamas de pele; Receio que apenas um homem adulto teria flocos tão grandes! Que pessoa imunda!",
	["她让我在这里等待，给您一些必要的指引。"] = "Ela me pediu para esperar aqui e lhe dar algumas orientações necessárias.",
	["她说——你看这两个人，穿得破，但靠在一起。"] = "Ela disse: olha essas duas pessoas, elas estão vestidas com trapos, mas estão apoiadas uma na outra.",
	["她说——剑已经全部落下了，不会再多了。"] = "Ela disse: todas as espadas caíram, não haverá mais nenhuma.",
	["她说以后不用再通信。"] = "Ela disse que não há mais necessidade de correspondência.",
	["她说只要一束红玫瑰，她就愿意和我去跳舞……"] = "Ela disse que desde que eu tenha um buquê de rosas vermelhas, ela estaria disposta a ir dançar comigo...",
	["她说她会前往东区书店，穿着深棕色的衣服，接过我递来的信物百合。"] = "Ela disse que iria à livraria no Distrito Leste, vestindo roupas marrons escuras, e pegaria a ficha de lírio que lhe entreguei.",
	["她说她很累，让我跟两个孩子说说话，她先休息一下，等我再看她的时候，她已经……已经停止了呼吸。"] = "Ela disse que estava cansada e me pediu para conversar com as duas crianças, e ela iria descansar um pouco. Quando olhei para ela novamente, ela tinha... parado de respirar.",
	["她说搭配的衣服？"] = "Ela disse roupas para combinar?",
	["她说，很久很久以前，在东方的东方，生活着一群巨人……"] = "Ela disse que há muito, muito tempo atrás, no leste do leste, vivia um grupo de gigantes...",
	["她谁都不会接受的。"] = "Ela não aceitará ninguém.",
	["她走了……不是说走过花海的心形小路，就能邂逅爱人吗？我走了一个月也没人爱上我！"] = "Ela se foi... não disseram que se você caminhasse pelo caminho em forma de coração em meio ao mar de flores, encontraria seu amante? Estou caminhando há um mês e ninguém se apaixonou por mim!",
	["她走了。去花丛里找找卡门的屁股……不，身体吧。"] = "Ela se foi. Vá procurar a bunda de Carmen... não, corpo nos arbustos de flores.",
	["她走了，让我把怀表交给你。"] = "Ela foi embora e me pediu para dar este relógio de bolso para você.",
	["她跟我一样，都是孤儿。我想，她是想跟我做朋友。她很温柔，会认真地跟我学妈妈的歌……"] = "Ela é órfã como eu. Acho que ela quer ser minha amiga. Ela é muito gentil e aprenderá sinceramente a canção da minha mãe comigo...",
	["她还在愚者教会，背后原因查清楚前禁止拜访。"] = "Ela ainda está na Igreja do Louco e as visitas são proibidas até que a causa subjacente seja esclarecida.",
	["她通常什么时候会消失？"] = "Quando ela geralmente desaparece?",
	["她那些无法倾诉的愤怒和委屈，都汇聚在了日记里。"] = "Toda a raiva e queixas que ela não podia confiar em ninguém foram despejadas em seu diário.",
	["她那天不知怎么的，\r\n似乎特别漂亮……\r\n就好像在等着我似的……"] = "Não sei o que aconteceu naquele dia, mas ela parecia excepcionalmente linda...\r\nEra como se ela estivesse esperando por mim...",
	["她都失踪好几周了！"] = "Ela está desaparecida há semanas!",
	["她需要一个不被注意的观察者，我能在这里找到自己的位置；我也能看见她的疲惫，提醒她停下来注意休息。我们总是在互相帮助。"] = "Ela precisa de um observador imperceptível, e posso encontrar meu lugar aqui; Também posso ver sua exaustão e lembrá-la de parar e descansar. Estamos sempre ajudando uns aos outros.",
	["她？"] = "Dela?",
	["好"] = "Bom",
	["好 出发！"] = "Tudo bem, vamos!",
	["好 我去找找看"] = "Bom, vou procurar.",
	["好,我去试试"] = "Tudo bem, vou tentar",
	["好……"] = "OK...",
	["好……上路！安妮，你跟好本杰明，我来把路打开。"] = "Tudo bem... vamos! Annie, fique perto de Benjamin, eu abrirei o caminho.",
	["好……但我还有其他事，只能帮你排一会。"] = "Ok... mas tenho outras coisas para fazer, só posso te ajudar por um tempo.",
	["好……好吧，这是因为我的家庭出了些变故，我不得已才出来谋生。但是我怕遇到那些富人，那些会去贝克兰德参加晚宴的富人们，也许会认出我……"] = "Bem, é porque minha família passou por algumas mudanças e eu tive que sair para ganhar a vida. Mas tenho medo de conhecer essas pessoas ricas, aquelas que iriam a Backlund para assistir aos bailes; eles podem me reconhecer...",
	["好……痛……好痛……"] = "Tão... doloroso... tão doloroso...",
	["好……谢谢你。"] = "Tudo bem... obrigado.",
	["好……这是我最后能为你们做的事……"] = "Tudo bem... esta é a última coisa que posso fazer por você...",
	["好……那就帮你排一会。"] = "Tudo bem... então vou esperar um pouco na fila por você.",
	["好、好好好，只要保护好我，你要多少钱都可以！"] = "Ok, ok, ok! Contanto que você me proteja, pagarei o que você quiser!",
	["好、好的。"] = "Tudo bem.",
	["好、好的。其实，我暂时也没钱给她下葬，还得攒几天，攒几天……还好最近天气凉快了。"] = "Tudo bem. Na verdade, ainda não tenho dinheiro para enterrá-la; Ainda preciso economizar para mais alguns dias... Ainda bem que o tempo esfriou recentemente.",
	["好、好的！"] = "Tudo bem!",
	["好、好的，谢谢您的关心，我会考虑的。"] = "Ok, obrigado pela sua preocupação. Vou considerar isso.",
	["好、好的，这么隆重？"] = "Ok, é tão formal?",
	["好、好的，长官！"] = "Sim, sim, senhor!",
	["好。"] = "OK.",
	["好。可能还会遇到别的危险，小心！"] = "Tudo bem. Podemos encontrar outros perigos, então tome cuidado!",
	["好。失踪案没有太多信息，不过他们的经历多少都和罗塞尔大帝有关。"] = "Bom. Não há muita informação sobre os casos de pessoas desaparecidas, mas suas experiências estão todas relacionadas, até certo ponto, ao Imperador Roselle.",
	["好。我们通过占卜确定，失踪地点只有三个，五月庄园、中央广场和廷根湖。"] = "OK. Através de adivinhação , determinamos que existem apenas três locais para os desaparecimentos: May Manor, Central Plaza e Tingen Lake.",
	["好。我先把这本资料还回去，然后马上出发。"] = "Tudo bem. Devolverei este documento primeiro e partiremos imediatamente.",
	["好。能见到你，就说明当年那张高塔，已经被你打成了逆位高塔。我不会再担心了。"] = "Bom. Ver você significa que a carta da Torre daquela época já foi jogada por você como uma Torre invertida. Não vou mais me preocupar.",
	["好一只生动的——"] = "Que vívido—",
	["好不容易全家来大城市，必须拍个全家福。"] = "Não é fácil vir toda a família para a cidade grande, é preciso tirar uma foto de família.",
	["好不容易找到的……怎么偏偏赶上阿尔杰先生回来，哎……"] = "Finalmente encontrei... por que teve que coincidir com o retorno do Sr. Alger, suspiro...",
	["好不容易熬出头了，孩子也有了体面的工作，谁能想到……那场该死的大雾霾……"] = "Eles finalmente conseguiram sobreviver, e a criança tinha um emprego decente, quem diria... aquela maldita Grande Névoa...",
	["好主意"] = "Boa ideia",
	["好主意——"] = "Boa ideia-",
	["好主意！粉色做成长裙，鹅黄色就做成花苞裙……"] = "Boa ideia! Vou mandar transformar o rosa em um vestido longo, e o amarelo ganso em uma saia tulipa...",
	["好主意，带我一个。"] = "Boa ideia, conte comigo.",
	["好久不见"] = "Muito tempo sem ver",
	["好久不见了，备受赞誉的名侦探阁下。"] = "Muito tempo sem nos ver, meu aclamado detetive.",
	["好久不见啊"] = "Muito tempo sem ver.",
	["好久不见，{{PlayerName}}。"] = "Faz muito tempo que não nos vemos, {{PlayerName}}.",
	["好久不见，卡萝队长。"] = "Há muito tempo que não nos vemos, Capitã Carol.",
	["好久没有这种一见钟情的感觉了，好开心啊。"] = "Já faz muito tempo que não sinto esse tipo de amor à primeira vista, tão feliz.",
	["好久没见到这么可爱的新人了。"] = "Já faz muito tempo que não vejo um recém-chegado tão fofo.",
	["好乖巧的松鼠。你是大自然的住户，还是迷途的客人？"] = "Que esquilo bem comportado. Você é um residente da natureza ou um convidado perdido?",
	["好乖的小猫！"] = "Uma gatinha tão bem comportada!",
	["好了"] = "Tudo bem",
	["好了 “正义”小姐该请我喝咖啡了"] = "Tudo bem, é hora da Srta. Justiça me convidar para um café.",
	["好了 你想先看哪张牌"] = "Tudo bem, qual cartão você deseja ver primeiro?",
	["好了。"] = "Tudo bem.",
	["好了。从今天起，你就是占卜俱乐部的正式会员，您的名字也已经在占卜师名册上了。"] = "Tudo bem. A partir de hoje você é membro oficial do Clube Adivinhação e seu nome já está na lista de adivinhos.",
	["好了。从今天起，你就是占卜家俱乐部的正式会员，您的名字也已经在占卜师名册上了。"] = "Lá. A partir de hoje você é membro oficial do Clube Adivinhação e seu nome já está na lista de adivinhos.",
	["好了。我们走的时候，可以去那边看一眼，但……"] = "Tudo bem. Quando sairmos, podemos dar uma olhada lá, mas...",
	["好了好了，你们都消停点。医生是体面人，哪能这么逼问。"] = "Tudo bem, tudo bem, acalmem-se. O médico é um homem decente, você não deveria pressioná-lo assim.",
	["好了好了，我知道你心仪的嘉宾是谁，当然也给她寄了邀请函，但是还没有收到回复。"] = "Tudo bem, tudo bem, eu sei quem é o seu convidado desejado. Claro, enviei um convite a ela, mas ainda não recebi resposta.",
	["好了好了，来客人了，去把后边新进的依兰原料拿来吧，奈拉小姐说晚上该做些新东西了。"] = "Tudo bem, tudo bem, um cliente está aqui. Vá buscar os ingredientes de ylang-ylang recém-chegados na parte de trás; A senhorita Naila disse que deveríamos fazer algo novo esta noite.",
	["好了好了，梅丽莎，我已经领会到你出色的数学天赋了。"] = "Tudo bem, tudo bem, Melissa. Já compreendi seu excelente talento matemático.",
	["好了好了，赶紧开始享用晚餐吧，我真的太饿了。"] = "Tudo bem, tudo bem, vamos começar a aproveitar o jantar, estou com muita fome.",
	["好了新人，回去好好睡一觉，你的工作明天才正式开始。"] = "Tudo bem, recém-chegado, volte e tenha uma boa noite de sono. Seu trabalho começa oficialmente amanhã.",
	["好了罗德先生，吃药后我们在这周围散散步吧。"] = "Tudo bem, Sr. Rhode, vamos dar uma volta por aqui depois de tomar o remédio.",
	["好了！"] = "Feito!",
	["好了！“正义”小姐该请我喝咖啡了。"] = "Tudo bem! Senhorita Justiça deveria me convidar para um café.",
	["好了！莉莉，能帮我把信送到佐特兰街2号吗？"] = "Tudo bem! Lily, você pode me ajudar a entregar uma carta na rua Zoutland, 2?",
	["好了！这是第一轮要用的药剂。"] = "Tudo bem! Esta é a poção a ser usada na primeira rodada.",
	["好了，今天就到这里吧。"] = "Tudo bem, vamos parar por aqui por hoje.",
	["好了，今天的拍摄就到这里了，期待与你的下次再会。"] = "Tudo bem, as filmagens de hoje terminam aqui, ansioso pelo nosso próximo encontro.",
	["好了，今天的聚会就到这里吧。"] = "Tudo bem, vamos encerrar a reunião de hoje aqui.",
	["好了，从现在起，让我来当告解室，而你是来向我做告解的。"] = "Tudo bem, de agora em diante, deixe-me ser o confessionário e você pode fazer sua confissão para mim.",
	["好了，你当大伙都是傻瓜么？这已经不是什么秘密了。"] = "Tudo bem, você acha que todo mundo é um tolo? Isso não é mais segredo.",
	["好了，你想先看哪张牌？"] = "Tudo bem, qual cartão você deseja ver primeiro?",
	["好了，做出你的决定吧，你已经没有多少时间可以浪费了。"] = "Tudo bem, tome sua decisão. Você não tem muito tempo a perder.",
	["好了，克莱恩·莫雷蒂先生，祝你今晚依旧有个好梦。"] = "Tudo bem, Sr. Klein Moretti, desejo-lhe um bom sonho novamente esta noite.",
	["好了，克莱恩，你可以开始通灵了。"] = "Tudo bem, Klein, você pode começar a Mediunidade Espiritual.",
	["好了，去吧。死了，也不用挨饿了。"] = "Tudo bem, vá em frente. Morto, não há mais necessidade de morrer de fome.",
	["好了，去告诉老尼尔吧。"] = "Tudo bem, vá contar ao Velho Neil.",
	["好了，尝尝吧。"] = "Tudo bem, experimente.",
	["好了，开玩笑的，不要那么紧绷着嘛，天塌下来个高的顶着。"] = "Tudo bem, estou brincando, não fique tão tenso. Se o céu cair, os altos o sustentarão.",
	["好了，弗莱，不论是相亲还是婚姻，都和调查非凡案件完全不同呀。"] = "Tudo bem, Frye, seja um encontro às cegas ou um casamento, é completamente diferente de investigar Beyonder casos.",
	["好了，当务之急是净化污染。请拿着这个。"] = "Tudo bem, a principal prioridade é purificar a corrupção. Por favor, pegue isso.",
	["好了，快把东西交出来……我们耐心有限。"] = "Tudo bem, apresse-se e entregue... nossa paciência é limitada.",
	["好了，我不在乎你在调查什么，这里每个人都有自己的秘密。"] = "Tudo bem, não me importa o que você está investigando; todos aqui têm seus próprios segredos.",
	["好了，我们只能说到这里了，我们还得升起这堆该死的火呢！"] = "Tudo bem, só podemos dizer isso; ainda temos que acender esse maldito fogo!",
	["好了，我们该出发了。"] = "Tudo bem, devemos partir.",
	["好了，我们该回庄园了。霍华德勋爵一家人会来参加今晚的晚宴，让女仆为你挑选一件美丽的衣服……"] = "Tudo bem, devemos voltar para a mansão. A família de Lord Howard estará presente no banquete desta noite, então deixe a empregada escolher um lindo vestido para você...",
	["好了，我明白。"] = "Tudo bem, eu entendo.",
	["好了，我要休息了……"] = "Tudo bem, vou descansar agora...",
	["好了，打起精神来！还有十几封信呢！"] = "Tudo bem, anime-se! Ainda restam mais de uma dúzia de cartas!",
	["好了，接下来有问题就问佐伊吧！"] = "Tudo bem, a seguir, se você tiver alguma dúvida, é só perguntar à Zoe!",
	["好了，爱德华，再分几个硬币给可怜的布莱特，让他祛祛身上的霉味。"] = "Tudo bem, Edward, dê mais algumas moedas ao pobre Bright para que ele possa se livrar do cheiro de mofo.",
	["好了，线索收集得差不多了，该回黑荆棘问问小阿诺德关于他这位“朋友”的事了。"] = "Tudo bem, as pistas são em sua maioria coletadas. É hora de voltar para Blackthorn e perguntar ao pequeno Arnold sobre seu “amigo”.",
	["好了，线索收集得差不多了，该回黑荆棘问问小阿诺德，关于他这位“朋友”的事了。"] = "Tudo bem, as pistas foram reunidas. É hora de voltar para Blackthorn e perguntar ao pequeno Arnold sobre esse “amigo” dele.",
	["好了，结束了。回去吧，回去吧……"] = "Tudo bem, acabou. Volte, volte...",
	["好了，还有什么需要我帮忙的吗？"] = "Tudo bem, há mais alguma coisa em que eu possa ajudar?",
	["好了，这次的历史之旅结束了，回去好好休息吧。期待下次再见。"] = "Tudo bem, esta jornada histórica acabou. Volte e descanse bem. Estou ansioso para ver você na próxima vez.",
	["好了？这颜色和气味……似乎不太好下咽"] = "Finalizado? Essa cor e esse cheiro... não parece muito fácil de engolir.",
	["好了？这颜色和气味……似乎不太好下咽。"] = "Feito? Essa cor e esse cheiro... não parece muito fácil de engolir.",
	["好了？！她在哪儿，我要去看她！"] = "Melhorar?! Onde ela está, eu quero vê-la!",
	["好些孩子？嗯……那再多给你一些。"] = "Muitas crianças? Hmm... então vou te dar um pouco mais.",
	["好人一生平安"] = "Pessoas boas vivem em paz",
	["好人一生平安！"] = "Pessoas boas vivem em paz!",
	["好任性"] = "Tão obstinado",
	["好优美的口风琴，是我出现幻觉了吗？"] = "Que linda melodia de gaita. Estou alucinando?",
	["好优美的语言"] = "Que linguagem linda",
	["好你个玛莎，我们合作这么久，你居然背着我在账上做手脚！"] = "Você, Martha, trabalhamos juntos há tanto tempo e você está realmente cozinhando os livros nas minhas costas!",
	["好像……一旦有大人靠近，她就不见了。"] = "Parece... que assim que um adulto se aproxima, ela desaparece.",
	["好像……大概……对不起，我真得好好思考一下这些问题。"] = "Parece... talvez... Me desculpe, eu realmente preciso pensar sobre essas questões com cuidado.",
	["好像……好一些了。我还需要做什么？"] = "Parece... um pouco melhor. O que mais eu preciso fazer?",
	["好像……成功了，我是一位真正的非凡者了！咦？"] = "Parece... eu consegui. Eu sou um verdadeiro Beyonder agora! Huh?",
	["好像……稍微好受点了。是奥黛丽小姐……"] = "Parece... que me sinto um pouco melhor. É a senhorita Audrey...",
	["好像……还是不对？"] = "Parece... ainda não está certo?",
	["好像……这杯没有什么特殊的感觉？"] = "Parece... esse copo não tem nenhum sentimento especial?",
	["好像…变成了猫，四处逛逛吧"] = "Parece... que você virou um gato; vá passear",
	["好像不对，再想想是敲几下来着？"] = "Isso não parece certo, deixe-me pensar novamente, quantas pancadas foram?",
	["好像不对，暗号是什么来着？"] = "Isso não parece certo, qual era a palavra-código mesmo?",
	["好像也没什么变化，树还是这棵树，土地还是这片地。"] = "Não parece que nada mudou. A árvore ainda é a mesma árvore, a terra ainda é a mesma terra.",
	["好像也没那么丑。"] = "Afinal, não parece tão feio.",
	["好像叫海莉。就在铁十字街拐角，一棵梧桐树下面。"] = "Acho que o nome dela é Hali. Bem na esquina da Iron Cross Street, debaixo de um plátano.",
	["好像可以从这边的洞口进去……"] = "Parece que posso entrar pela abertura aqui...",
	["好像吵起来了，快去看看吧。"] = "Eles parecem estar discutindo, vamos dar uma olhada.",
	["好像在……画画？他不让我看，连靠近都不行！"] = "Parece que... desenhando? Ele não me deixa olhar, nem chegar perto!",
	["好像在研制某种药剂？这是我听到的药剂配方，很新奇的角度，我最近正在研究。"] = "Parece estar desenvolvendo algum tipo de poção? Esta é a fórmula da poção que ouvi; é uma perspectiva muito nova que tenho pesquisado recentemente.",
	["好像就是这里……"] = "Parece que está aqui...",
	["好像忘了什么……我的记性怎么跟队长一样差了？"] = "Sinto que esqueci alguma coisa... por que minha memória é tão ruim quanto a do Capitão?",
	["好像是一本童话书。"] = "Parece ser um livro de conto de fadas.",
	["好像是一道传送门。"] = "Parece ser um portal.",
	["好像是做不到，连我的爷爷和父亲也不行。"] = "Acho que não podem, nem meu avô e meu pai conseguiram.",
	["好像是男盥洗室传出的声音……刚才怎么没听见？不管了，去看看！"] = "Parece que o barulho vem do banheiro masculino... por que não ouvi agora? Não importa, vamos verificar!",
	["好像是男盥洗室传出的声音……男就男吧，我得去看看！"] = "Parece que o barulho vem do banheiro masculino... bem, é masculino, tenho que verificar!",
	["好像是的，但你已经画得很好了。"] = "Parece que sim, mas você já pintou muito bem.",
	["好像是这个方向……"] = "Parece que está nessa direção...",
	["好像是这么回事。"] = "Parece que é esse o caso.",
	["好像有一个……小女孩？"] = "Parece haver uma... garotinha?",
	["好像有人在争吵……听听发生了什么吧。"] = "Parece que alguém está discutindo... vamos ouvir o que está acontecendo.",
	["好像有人在哭泣……"] = "Alguém parece estar chorando...",
	["好像有人来了"] = "Parece que alguém está vindo",
	["好像有什么东西在呼唤我？"] = "Parece que algo está me chamando?",
	["好像有什么东西被点亮了……"] = "Parece que algo foi aceso...",
	["好像有呼救声？是从下面传来的。"] = "Parece que há um pedido de ajuda? Está vindo de baixo.",
	["好像有更多力量涌入了身体……"] = "Parece que mais poder surgiu em meu corpo...",
	["好像某种无形的密封消失了……"] = "Parece que algum tipo de selo invisível desapareceu...",
	["好像没办法沟通啊。"] = "Parece que não há como se comunicar.",
	["好像没有反应……"] = "Parece que não há resposta...",
	["好像没有那种边界了，循环……会就此结束吗？"] = "Parece que esse limite desapareceu. O ciclo... terminará aqui?",
	["好像看到了什么"] = "Parece ter visto algo",
	["好像身体里的力量忽然消失，但又回来了？"] = "Parece que o poder do meu corpo desapareceu de repente, mas depois voltou?",
	["好像还挺举手之劳的……"] = "Parece que é um pequeno favor...",
	["好冷……"] = "Tão frio...",
	["好冷……安西娅不要被……丢下……"] = "Tão frio... Anthea não quer ser... deixada para trás...",
	["好凶……"] = "Tão feroz...",
	["好别扭的家伙，让我亲自去给这家伙好好上一课！"] = "Que cara estranho, deixe-me ir e dar-lhe uma boa lição!",
