	["好友<img id=\"#115\" width=\"24\" height=\"24\" valign=\"0.5\"/>签名好友签名好友签名好友签名"] = "Amigo <img id=\"#115\" width=\"24\" height=\"24\" valign=\"0.5\"/> Assinatura Assinatura do Amigo Assinatura do Amigo",
