	["归属："] = "Afiliação:",
	["归序净化之台"] = "Altar da Purificação Ordenada",
	["归序净化之台-文字版"] = "Plataforma de Purificação Ordenada - Versão Texto",
	["归来水手"] = "Marinheiro retornando",
	["归类"] = "Categorizar",
