	["环境"] = "Ambiente",
	["环境\n光照"] = "Ambiente \n Iluminação",
	["环境与科学"] = "Meio Ambiente e Ciência",
	["环境交互效果"] = "Efeitos de interação ambiental",
	["环境交互说明"] = "Instruções de interação ambiental",
