	["观众-绝技1段"] = "Spectator - Ultimate Skill Phase 1",
	["观众-绝技2段"] = "Spectator - Ultimate Skill Phase 2",
	["观众-绝技额外治疗"] = "Spectator-Ultimate Extra Healing",
