	["观众1小男孩"] = "Spectator 1 Little Boy",
	["观众2"] = "Spectator 2",
	["观众2胖女"] = "Spectator 2 Fat Woman",
	["观众2青年女"] = "Spectator 2 Young Woman",
	["观众3"] = "Spectator 3",
	["观众30级橙装属性"] = "Spectator Level 30 Orange Equipment Stats",
	["观众3富贵胖女"] = "Spectator 3 Wealthy Fat Woman",
	["观众4"] = "Spectator 4",
