	["认清自己的脆弱。"] = "Recognize your own fragility.",
	["认真一拳"] = "Serious Punch",
	["认真的"] = "Serious",
	["认真的？"] = "Are you serious?",
	["认知税"] = "Cognition Tax",
	["认知税+"] = "Cognition Tax+",
	["认知经验"] = "Cognitive Experience",
	["认知经验，用于提升扮演等级和神性等级。"] = "Cognition Experience, used to increase Acting level and divinity level.",
	["认识第一纪元"] = "Understand the First Epoch",
	["认识第三纪元"] = "Know the Third Epoch",
