	["造成的伤害提高100%"] = "Damage dealt increased by 100%",
	["造成的伤害提高100%，受到的伤害提高80%"] = "Damage dealt increased by 100%, damage taken increased by 80%",
	["造成的伤害提高200%，受到的伤害提高200%"] = "Damage dealt increased by 200%, damage taken increased by 200%",
	["造成的伤害提高300%，受到的伤害提高330%"] = "Damage dealt increased by 300%, damage taken increased by 330%",
	["造成的伤害提高{*.2f**,F1690001,SkillMulti}，受到目标伤害减免的抵消。"] = "Damage dealt is increased by {*.2f**,F1690001,SkillMulti}, offset by the target's Damage Reduction.",
	["造成的伤害提高，受到目标减伤的抵消。"] = "Damage dealt is increased, offset by the target's Damage Reduction.",
	["造成的伤害降低*f**"] = "Damage dealt reduced by *f**.",
	["造成的伤害降低30%，受到的伤害降低60%，每秒回复2%最大生命"] = "Damage dealt reduced by 30%, damage taken reduced by 60%, recover 2% of max Health per second",
	["造成的最终伤害提高{*d,F1690001,DeltaHurt}点。"] = "Final damage dealt is increased by {*d,F1690001,DeltaHurt} points.",
	["造成的治疗效果提高{*.1f**,F1690001,HealMulti}。"] = "Healing effects caused are increased by {*.1f**,F1690001,HealMulti}.",
	["造成的物理伤害提高{*.1f**,F1690001,pHurtMulti}，受到目标物理减伤的抵消。"] = "Physical damage dealt is increased by {*.1f**,F1690001,pHurtMulti}, offset by the target's Physical Damage Reduction.",
	["造成的魔法伤害提高{*.1f**,F1690001,mHurtMulti}，受到目标魔法减伤的抵消。"] = "Magic damage dealt is increased by {*.1f**,F1690001,mHurtMulti}, offset by the target's Magic Damage Reduction.",
	["造成范围伤害并且自身受到的伤害降低。"] = "Deals area damage and reduces damage taken by the user.",
	["造梦大师"] = "Dream-Weaving Master",
	["造物主从混沌中醒来，打破了幽暗，制造了第一缕光，自己则彻底融入宇宙，化身为万物……"] = "The Creator woke up from chaos, broke the darkness, created the first ray of light, and then completely merged into the universe, becoming all things...",
	["造访心屿"] = "Visit the Island of Mind",
	["逮住那个凶手！"] = "Catch that murderer!",
	["逮捕"] = "Arrest",
	["逮捕我，请问这是为什么？我从未有过任何违背法律的行径。"] = "Arresting me? May I ask why? I have never committed any act against the law.",
	["逸"] = "Sim",
	["逸君"] = "Yi junho",
	["逸墨"] = "Yi Mo",
	["逸思"] = "Yi Si",
	["逸散蠹虫"] = "Stray Bookworm",
	["逸散谜虫"] = "Stray Mystery Insect",
